mapper.select:
/* master.mpst.selectReturnStatsBuyerList */ SELECT X.YYYYMM, X.COM_CODE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.COM_CODE) AS COM_NAME, X.KEP_DEPT, DECODE(X.KEP_DEPT, 'XX', '미지정', (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = 'KRKORE0001' AND TYPE = 'C001' AND CODE = X.KEP_DEPT)) AS KEP_DEPT_NAME, X.PO_CNT, X.WMRE_CNT, DECODE(X.PO_CNT, 0, 0, ROUND((X.WMRE_CNT / X.PO_CNT * 100), 1)) AS CNT_RATE, X.PO_AMT, X.WMRE_AMT, DECODE(X.PO_AMT+X.WMRE_AMT, 0, 0, ROUND((X.WMRE_AMT / (X.PO_AMT+X.WMRE_AMT) * 100), 1)) AS AMT_RATE FROM ( SELECT A.YYYYMM, A.COM_CODE, NVL((SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE YEAR = TO_CHAR(SYSDATE, 'YYYY') AND BUYER = A.COM_CODE AND STATUS = 'C'), 'XX') AS KEP_DEPT, A.PO_CNT, A.WMRE_CNT, A.PO_AMT, A.WMRE_AMT FROM KEPWMRE_MNG A WHERE 1=1 AND A.YYYYMM = #{st_yyyymm} AND A.ST_TYPE = 'B' AND A.WMRE_CNT > 0 ) X WHERE 1=1
AND X.KEP_DEPT = #{st_dept_code}
ORDER BY X.WMRE_CNT DESC, X.COM_CODE

/* master.mpst.selectReturnStatsAgentList */ SELECT X.YYYYMM, X.COM_CODE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.COM_CODE) AS COM_NAME, X.KEP_DEPT, DECODE(X.KEP_DEPT, 'XX', '미지정', (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = 'KRKORE0001' AND TYPE = 'C001' AND CODE = X.KEP_DEPT)) AS KEP_DEPT_NAME, X.PO_CNT, X.WMRE_CNT, DECODE(X.PO_CNT, 0, 0, ROUND((X.WMRE_CNT / X.PO_CNT * 100), 1)) AS CNT_RATE, X.PO_AMT, X.WMRE_AMT, DECODE(X.PO_AMT+X.WMRE_AMT, 0, 0, ROUND((X.WMRE_AMT / (X.PO_AMT+X.WMRE_AMT) * 100), 1)) AS AMT_RATE FROM ( SELECT A.YYYYMM, A.COM_CODE, A.PO_CNT, A.WMRE_CNT, A.PO_AMT, A.WMRE_AMT, A.WMRE_TYPE4 AS KEP_DEPT FROM KEPWMRE_MNG A WHERE 1=1 AND A.YYYYMM = #{st_yyyymm} AND A.ST_TYPE = 'S' AND A.WMRE_CNT > 0 ) X WHERE 1=1
AND X.KEP_DEPT = #{st_dept_code}
ORDER BY X.WMRE_CNT DESC, X.COM_CODE
